import { mergeProps, type JSX } from 'solid-js'
import { Dynamic } from 'solid-js/web'

import { claimSlot, scope, type Defaults } from '@polymorph/solid'

export type Tone = NonNullable<ToneScopeProps['value']>

export type ScopeElement = NonNullable<ToneScopeProps['as']>

export interface ToneScopeProps {
  as?: 'div' | 'section' | 'span'
  children?: JSX.Element
  value: 'inverse'
}

/** Rung 2 of the exception ladder (`docs/rules.md`): a contextual scope. */
export default function ToneScope(given: ToneScopeProps): JSX.Element {
  const props = mergeProps({ as: 'div' } as Defaults<ToneScopeProps, 'as'>, claimSlot(given))
  return scope(() => {
    return (
      <Dynamic component={props.as} data-tone={props.value}>
        {props.children}
      </Dynamic>
    )
  })
}
